import{_ as e,o as r,c as o,ao as d}from"./chunks/framework.BSzmyLFO.js";const p=JSON.parse('{"title":"LAPACK / BLAS coverage","description":"","frontmatter":{},"headers":[],"relativePath":"coverage.md","filePath":"coverage.md","lastUpdated":null}'),s={name:"coverage.md"};function a(n,t,i,l,g,c){return r(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="LAPACK-/-BLAS-coverage" tabindex="-1">LAPACK / BLAS coverage <a class="header-anchor" href="#LAPACK-/-BLAS-coverage" aria-label="Permalink to &quot;LAPACK / BLAS coverage {#LAPACK-/-BLAS-coverage}&quot;">​</a></h1><p>This page tracks which <code>LinearAlgebra</code> operations route to PureBLAS after <code>PureBLAS.activate()</code>, and their optimization status.</p><p><strong>Legend</strong></p><ul><li><p><strong>Routes</strong> — the routine forwards to PureBLAS via LBT after <code>activate()</code> (or is composed from routines that do).</p></li><li><p><strong>Optimized</strong> — ✅ perf-gated <code>≥ max(OpenBLAS, AOCL)</code> on the dev fleet (Zen3/4/5); ⏳ correctness-first (numerically LAPACK-accurate, blocked/SIMD perf tuning is a documented follow-up); — n/a. Both references are always measured: a routine can beat one by a wide margin and lose to the other, and a large win over a library that did not implement a routine is not evidence of speed (AOCL&#39;s packed Cholesky is ~6× slower than OpenBLAS&#39;s — near-reference code — so beating it there means little). Where a footnote gives numbers, it names the reference.</p></li><li><p>Element types: <strong>s</strong> = Float32, <strong>d</strong> = Float64, <strong>c</strong> = ComplexF32, <strong>z</strong> = ComplexF64.</p></li></ul><h2 id="BLAS" tabindex="-1">BLAS <a class="header-anchor" href="#BLAS" aria-label="Permalink to &quot;BLAS {#BLAS}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Level</th><th style="text-align:right;">Routines</th><th style="text-align:right;">Types</th><th style="text-align:right;">Routes</th><th style="text-align:right;">Optimized</th></tr></thead><tbody><tr><td style="text-align:right;">BLAS-1</td><td style="text-align:right;">axpy, scal, copy, dot, nrm2, asum, iamax, rot, swap</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">✅</td></tr><tr><td style="text-align:right;">BLAS-1 complex dot</td><td style="text-align:right;">dotu, dotc</td><td style="text-align:right;">c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">✅</td></tr><tr><td style="text-align:right;">BLAS-2</td><td style="text-align:right;">gemv, ger, symv, hemv, trmv, trsv, banded, packed</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">✅</td></tr><tr><td style="text-align:right;">BLAS-3</td><td style="text-align:right;">gemm, symm, hemm, syrk, herk, syr2k, her2k, trmm, trsm</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">✅</td></tr></tbody></table><p>GEMM additionally uses Strassen–Winograd (real) and Karatsuba 3M (complex) above a size crossover — <strong>beats</strong> OpenBLAS at large <code>n</code>.</p><h2 id="LAPACK-—-factorizations-and-solves" tabindex="-1">LAPACK — factorizations &amp; solves <a class="header-anchor" href="#LAPACK-—-factorizations-and-solves" aria-label="Permalink to &quot;LAPACK — factorizations &amp; solves {#LAPACK-—-factorizations-and-solves}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Op</th><th style="text-align:right;">Routines</th><th style="text-align:right;">Types</th><th style="text-align:right;">Routes</th><th style="text-align:right;">Optimized</th></tr></thead><tbody><tr><td style="text-align:right;">Cholesky</td><td style="text-align:right;">potrf, potrs, potri</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">✅ <sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></td></tr><tr><td style="text-align:right;">Pivoted Cholesky</td><td style="text-align:right;">pstrf</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">⏳ <sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup></td></tr><tr><td style="text-align:right;">LU</td><td style="text-align:right;">getrf, getrs, getri, gesv</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">✅ <sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1:1]</a></sup></td></tr><tr><td style="text-align:right;">QR</td><td style="text-align:right;">geqrf, geqrt, gemqrt, orgqr, ormqr</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">✅</td></tr><tr><td style="text-align:right;">LQ</td><td style="text-align:right;">gelqf, orglq, ormlq</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">⏳</td></tr><tr><td style="text-align:right;">QL / RQ</td><td style="text-align:right;">geqlf, gerqf, org/orm ql/rq</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">⏳</td></tr><tr><td style="text-align:right;">Pivoted QR</td><td style="text-align:right;">geqp3</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">⏳ <sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></td></tr><tr><td style="text-align:right;">RZ (for gelsy)</td><td style="text-align:right;">tzrzf, ormrz</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">⏳</td></tr><tr><td style="text-align:right;">Bunch–Kaufman</td><td style="text-align:right;">sytrf, hetrf, sytrs, hetrs</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">⏳ <sup class="footnote-ref"><a href="#fn3" id="fnref3:1">[3:1]</a></sup></td></tr><tr><td style="text-align:right;">Indefinite solve/inv</td><td style="text-align:right;">sysv, hesv, sytri, hetri</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">⏳</td></tr><tr><td style="text-align:right;">Triangular</td><td style="text-align:right;">trtrs, trtri, trcon</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">✅</td></tr><tr><td style="text-align:right;">Condition est.</td><td style="text-align:right;">gecon, pocon, trcon</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">⏳</td></tr><tr><td style="text-align:right;">Least-squares</td><td style="text-align:right;">gels</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">✅ <sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup></td></tr><tr><td style="text-align:right;">Rank-deficient LS</td><td style="text-align:right;">gelsd, gelsy</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">⏳</td></tr></tbody></table><h2 id="LAPACK-—-SVD" tabindex="-1">LAPACK — SVD <a class="header-anchor" href="#LAPACK-—-SVD" aria-label="Permalink to &quot;LAPACK — SVD {#LAPACK-—-SVD}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Op</th><th style="text-align:right;">Routines</th><th style="text-align:right;">Types</th><th style="text-align:right;">Routes</th><th style="text-align:right;">Optimized</th></tr></thead><tbody><tr><td style="text-align:right;">SVD (values+vectors)</td><td style="text-align:right;">gesvd, gesdd, gebrd, bdsqr, bdsdc</td><td style="text-align:right;">s/d</td><td style="text-align:right;">✅</td><td style="text-align:right;">✅</td></tr><tr><td style="text-align:right;">SVD complex</td><td style="text-align:right;">gesvd, gesdd (z/c)</td><td style="text-align:right;">c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">⏳</td></tr><tr><td style="text-align:right;">Generalized SVD</td><td style="text-align:right;">ggsvd, ggsvd3</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅ (rank-deficient)</td><td style="text-align:right;">⏳</td></tr></tbody></table><h2 id="LAPACK-—-eigensolvers" tabindex="-1">LAPACK — eigensolvers <a class="header-anchor" href="#LAPACK-—-eigensolvers" aria-label="Permalink to &quot;LAPACK — eigensolvers {#LAPACK-—-eigensolvers}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Op</th><th style="text-align:right;">Routines</th><th style="text-align:right;">Types</th><th style="text-align:right;">Routes</th><th style="text-align:right;">Optimized</th></tr></thead><tbody><tr><td style="text-align:right;">Symmetric / Hermitian</td><td style="text-align:right;">syev, syevd, syevr, heev, sytrd, hetrd, stedc, steqr, sterf, ormtr</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">✅</td></tr><tr><td style="text-align:right;">Sym-tridiagonal</td><td style="text-align:right;">stev, stegr, stebz, stein</td><td style="text-align:right;">s/d</td><td style="text-align:right;">✅</td><td style="text-align:right;">⏳</td></tr><tr><td style="text-align:right;">Generalized symmetric</td><td style="text-align:right;">sygvd, hegvd</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">⏳</td></tr><tr><td style="text-align:right;">Nonsymmetric</td><td style="text-align:right;">geev, geevx, gebal, gehrd, hseqr, trevc, gebak</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">⏳</td></tr><tr><td style="text-align:right;">Schur</td><td style="text-align:right;">gees</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">⏳</td></tr><tr><td style="text-align:right;">Generalized nonsym (QZ)</td><td style="text-align:right;">ggev, gges, gghrd, hgeqz, tgevc</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">⏳</td></tr><tr><td style="text-align:right;">Schur reordering</td><td style="text-align:right;">trexc, trsen</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">⏳</td></tr><tr><td style="text-align:right;">Sylvester / Lyapunov</td><td style="text-align:right;">trsyl</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">⏳</td></tr></tbody></table><p><strong>Symmetric / Hermitian eigensolver</strong> gates <code>≥ max(OpenBLAS, AOCL)</code> at every size on the whole fleet (Zen3/4/5), all four types and both <code>jobz</code>. Three Level-3 pieces get it there: the two-sided reduction (<code>sytrd</code>/<code>hetrd</code>) is blocked <code>dlatrd</code>+<code>syr2k</code>/<code>her2k</code>; the eigenvector back-transform (<code>ormtr</code>/<code>unmtr</code>) is compact-WY block reflectors; and the divide-and-conquer solver (<code>stedc</code>) assembles eigenvectors once (no per-merge column copies) and combines survivors with the <code>dlaed3</code> COLTYP <strong>two half-height gemms</strong> (exploiting the block-diagonal zero structure — ~half the combine flops, matching libFLAME).</p><h2 id="LAPACK-—-banded-/-tridiagonal-/-packed" tabindex="-1">LAPACK — banded / tridiagonal / packed <a class="header-anchor" href="#LAPACK-—-banded-/-tridiagonal-/-packed" aria-label="Permalink to &quot;LAPACK — banded / tridiagonal / packed {#LAPACK-—-banded-/-tridiagonal-/-packed}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Op</th><th style="text-align:right;">Routines</th><th style="text-align:right;">Types</th><th style="text-align:right;">Routes</th><th style="text-align:right;">Optimized</th></tr></thead><tbody><tr><td style="text-align:right;">General banded LU</td><td style="text-align:right;">gbtrf, gbtrs</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">⏳ <sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup></td></tr><tr><td style="text-align:right;">General tridiagonal</td><td style="text-align:right;">gtsv, gttrf, gttrs</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">✅</td></tr><tr><td style="text-align:right;">SPD tridiagonal</td><td style="text-align:right;">pttrf, pttrs, ptsv</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">✅ <sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup></td></tr><tr><td style="text-align:right;">Banded Cholesky</td><td style="text-align:right;">pbtrf, pbtrs</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">⏳ <sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup></td></tr><tr><td style="text-align:right;">Packed Cholesky</td><td style="text-align:right;">pptrf, pptrs</td><td style="text-align:right;">s/d/c/z</td><td style="text-align:right;">✅</td><td style="text-align:right;">⏳ <sup class="footnote-ref"><a href="#fn8" id="fnref8">[8]</a></sup></td></tr></tbody></table><h2 id="Free-via-composition" tabindex="-1">Free via composition <a class="header-anchor" href="#Free-via-composition" aria-label="Permalink to &quot;Free via composition {#Free-via-composition}&quot;">​</a></h2><p><code>exp</code>, <code>sqrt</code>, <code>log</code>, <code>^</code> of a matrix, <code>sylvester</code>/<code>lyap</code>, <code>pinv</code>, <code>nullspace</code>, <code>rank</code>, <code>cond</code>, <code>factorize</code> — computed in Julia on top of the routed <code>eigen</code>/<code>schur</code>/<code>svd</code>/<code>\\</code> kernels; no separate LAPACK wrapper needed.</p><h2 id="OpenBLAS-fallthrough:-ZERO" tabindex="-1">OpenBLAS fallthrough: ZERO <a class="header-anchor" href="#OpenBLAS-fallthrough:-ZERO" aria-label="Permalink to &quot;OpenBLAS fallthrough: ZERO {#OpenBLAS-fallthrough:-ZERO}&quot;">​</a></h2><p><strong>Every LAPACK symbol <code>LinearAlgebra</code> can <code>ccall</code> now forwards to PureBLAS after <code>activate()</code></strong> — including the auxiliaries (<code>larf</code>/<code>larfg</code>/<code>lacpy</code>), the driver internals (<code>gebrd</code>/<code>bdsqr</code>/<code>bdsdc</code>/<code>hseqr</code>/<code>trevc</code>/<code>gebak</code>/<code>sytrd</code>/<code>hetrd</code>/<code>orgtr</code>/<code>ormtr</code>), the combined and expert drivers (<code>gesv</code>, <code>posv</code>, <strong><code>gesvx</code></strong> with equilibration + iterative refinement + condition/error bounds), the reordering routines (<code>trexc</code>/<code>trsen</code>/<strong><code>tgsen</code></strong>, real <em>and</em> complex — the real path does the 2×2 conjugate-pair swap), <strong><code>trrfs</code></strong>, <strong><code>syconv</code></strong>, complex <strong><code>bdsqr</code></strong>, and the <strong>rank-deficient generalized SVD</strong> (<code>ggsvd</code>, all s/d/c/z). This is enforced by a machine-checkable ratchet test (<code>test/lbt_forward_tests.jl</code>) that enumerates every symbol the stdlib wraps and asserts the fallthrough count is <strong>0</strong>.</p><p>The only two names excluded from the count are <code>cstev_</code>/<code>zstev_</code>, which are <strong>not real LAPACK symbols</strong> — they appear only in commented-out lines of the stdlib and have no OpenBLAS export.</p><h2 id="Summary" tabindex="-1">Summary <a class="header-anchor" href="#Summary" aria-label="Permalink to &quot;Summary {#Summary}&quot;">​</a></h2><ul><li><p><strong>BLAS 1/2/3 and the core dense factorizations (Cholesky, LU, QR, SVD real+complex+F32) are routed AND perf-gated <code>≥ OpenBLAS</code>.</strong></p></li><li><p><strong>Everything else routable through the <code>LinearAlgebra</code> API</strong> — all eigensolvers (symmetric, Hermitian, nonsymmetric, generalized, Schur), Sylvester/Schur-reordering, the expert general solver (<code>gesvx</code>), generalized SVD, and the remaining factorizations (indefinite, QL/RQ, RZ, pivoted Cholesky, banded/tridiagonal/packed, rank-deficient LS) — <strong>is routed and numerically LAPACK-accurate, correctness-first</strong>. The <code>≥ OpenBLAS</code> performance gate for this second tier (blocked <code>dlaqr0</code> multishift+AED, blocked <code>dlahr2</code>, SIMD Bunch-Kaufman/QZ, blocked complex <code>zunmbr</code>, a convergent perf <code>dbdsqr</code>, …) is a scheduled follow-up campaign.</p></li><li><p>The coverage audit (the ratchet gate) confirms <strong>zero OpenBLAS fallthrough</strong>: after <code>activate()</code>, the OpenBLAS fallback is fully removed.</p></li></ul><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>The ✅ on these rows is for the <strong>factorizations</strong>; their <strong>solves are not yet gated</strong>, and the distinction is worth stating because the solves were invisible for a long time. <code>getrs</code>/<code>potrs</code>/<code>trtrs</code> had no native entry point until 2026-07-29, so they could not be measured at all — the harness compares <code>PureBLAS.foo!</code> against <code>LAPACK.foo!</code> and there was nothing to call. Adding one exposed <code>A \\ b</code> with a single right-hand side running <strong>14× slower than OpenBLAS</strong>, traced to three defects in <code>trsm</code>: a blocked setup never repaid for narrow B, a power-of-two-<code>lda</code> A-pad that cost +3–357% across all sixteen operand combinations and paid nowhere, and a <strong>ragged SIMD lane charged as a full lane</strong> (<code>nrhs</code>=1…7 each cost what eight columns cost together). After those, Zen4 gate sweep: vs <strong>OpenBLAS</strong> <code>getrs</code> geomean 1.05 / worst 0.99, <code>potrsL</code> 2.20 / 0.93, <code>potrsU</code> 2.74 / 1.07 ✓, <code>trtrs</code> 1.11 / 1.02 ✓ — <code>potrs</code> reaching <strong>4.9×</strong> at n=1024. vs <strong>AOCL</strong> they still miss: <code>getrs</code> 0.93 / 0.85, <code>potrsL</code> 0.94 / 0.78, <code>potrsU</code> 1.13 / 0.91, <code>trtrs</code> 1.07 / 0.88. So under <code>max(OB, AOCL)</code> the solves remain open, and <code>trsm</code> itself passes OpenBLAS (worst 1.18, up from 1.04) while still missing AOCL (worst 0.90). A residual sits at <code>nrhs = 8</code>, between the two mechanisms — too wide for the per-column sweep, and on Zen3 (<code>W=4</code>) already two full lanes, so the ragged-tail fix does not reach it. <a href="#fnref1" class="footnote-backref">↩︎</a> <a href="#fnref1:1" class="footnote-backref">↩︎</a></p></li><li id="fn2" class="footnote-item"><p><code>pstrf</code>&#39;s blocked pivoted factorization clears <strong>AOCL completely on both Zen4 and Zen5</strong>, both triangles, every size (Zen5: <code>uplo=&#39;L&#39;</code> 1.07–1.75, <code>uplo=&#39;U&#39;</code> 1.06–1.75). Against <strong>OpenBLAS</strong> it clears everywhere except a narrow <code>uplo=&#39;U&#39;</code> window that is consistent across µarchs and mild: Zen4 n=48 <strong>0.943</strong> and n=64 <strong>0.921</strong>; Zen5 n=64 <strong>0.978</strong> only. Everything else runs 1.01–1.99. Those cells were known but had never been <em>gated</em> — the harness passed <code>uplo=&#39;L&#39;</code> for both sides, so the separate &#39;U&#39; code path (the pivoted panel and the trailing update both mirror) was never measured. A <code>pstrfU</code> row now tracks it. The large-n wins come from batching the pivot row swaps per panel: they are stride-<code>lda</code> and were ~47% of the runtime, so the swap — not the BLAS-3 update — was the bottleneck. ⚠ Float64; Zen3 not yet measured for this routine. One caveat on reading the published table: the Zen4 gate sweep reports <code>pstrf</code> worst = 0.85 vs OpenBLAS, which is <strong>not</strong> one of the cells above — it is n=8, where the per-round ratios come out bimodal (1.03 / 1.00 / 0.79 / 1.01 / 1.01 / 0.79 / 0.80 / 1.03). Rounds alternating like that at sub-microsecond scale is the ABBA ordering effect, not a stable regression; the sweep&#39;s size grid (8, 32, 128, …) skips 48 and 64 entirely, so it never samples the real residual. <a href="#fnref2" class="footnote-backref">↩︎</a></p></li><li id="fn3" class="footnote-item"><p><strong>Measured as unblocked.</strong> <code>geqp3</code> and <code>sytrf</code>/<code>sytrs</code> are BLAS-2 implementations racing blocked BLAS-3 ones, and their ratios degrade monotonically with <code>n</code> — the signature. Zen4 gate sweep (geomean / worst, n = 8…4096): <code>geqp3</code> <strong>0.34 / 0.18</strong> vs OpenBLAS and <strong>0.31 / 0.17</strong> vs AOCL — the worst routine in the real LAPACK surface; <code>sytrf</code> <strong>0.56 / 0.15</strong> and 0.59 / 0.15; <code>sytrs</code> 0.86 / 0.52 and 1.10 / 0.47. Both are confirmed from source, not inferred: <code>geqp3.jl</code>&#39;s header states it is the unblocked core, and <code>sytrf!</code> calls <code>_sytf2_*</code> directly with no blocked driver at all. These had <strong>never been benchmarked</strong> before 2026-07-29 — they routed and passed correctness, which reads as coverage while measuring nothing. A blocked <code>dlaqps</code> port for <code>geqp3</code> was written and <strong>verified correct</strong> (pivots and R identical to LAPACK, reconstruction to 1e-13, over full-rank/rank-deficient/graded input) but was <strong>not faster</strong>, and larger panels were <em>worse</em> — the diagnostic that the cost is the panel&#39;s own per-column BLAS-2 calls, not the trailing gemm. It is reverted, not shipped. The retry must reach the kernels pointer-direct; see §5 of <a href="./tuning">Tuning</a> and the note on <code>sytrs</code>, where two codegen hazards (an unforwarded store-to-load and a per-element <code>herm ?</code> branch) were worth +11–18%. <a href="#fnref3" class="footnote-backref">↩︎</a> <a href="#fnref3:1" class="footnote-backref">↩︎</a></p></li><li id="fn4" class="footnote-item"><p><code>gels</code> clears <strong>both</strong> references on the Zen4 gate sweep — geomean 2.42 / worst 1.93 vs OpenBLAS, 1.88 / 1.28 vs AOCL. Worth noting as a control alongside the ⏳ rows above: it composes <code>geqrf</code> + <code>trsm</code>, both already tuned, which is consistent with the others&#39; problem being their own kernels rather than anything shared. It was also never benchmarked before 2026-07-29 — this row changed from ⏳ to ✅ on measurement, not on work. <a href="#fnref4" class="footnote-backref">↩︎</a></p></li><li id="fn5" class="footnote-item"><p><code>gbtrf</code> has no clean shape — Zen4 vs OpenBLAS 1.44 / 1.30 / 0.79 / 1.11 / 1.08 / 0.66 at n = 32…1024, and vs AOCL 1.06 / 0.89 / 0.60 / 1.25 / 1.12 / 0.44 (gate sweep: 0.96 / 0.48 and 0.78 / 0.34). The dips at n=128 and n=1024 are undiagnosed and should not be assumed to share a cause with the unblocked routines above. <a href="#fnref5" class="footnote-backref">↩︎</a></p></li><li id="fn6" class="footnote-item"><p>All six tridiagonal routines gate <code>≥ max(OpenBLAS, AOCL)</code> on Zen3/4/5 with one exception: <code>pttrs</code> measures 0.99 against AOCL (1.67–1.73 vs OpenBLAS). That is a <em>shared</em> dependency-chain bound, not a gap — both libraries run at ~12.2 cyc/elem, which is the analytic 2×(multiply+subtract) limit for the pair of triangular sweeps, with 0.0% run-to-run drift. See &quot;Tridiagonal&quot; in <a href="./performance">Performance</a>. <a href="#fnref6" class="footnote-backref">↩︎</a></p></li><li id="fn7" class="footnote-item"><p><code>pbtrf</code> gates fully on <strong>Zen4</strong> (Float64, <code>kd = 32…384</code>, n ∈ {1024, 4096}, both triangles: 1.02–3.28× AOCL, 1.49–2.00× OpenBLAS) and beats <strong>OpenBLAS on all three µarchs</strong>, but it does <strong>not</strong> yet clear AOCL fleet-wide — which is why this row is ⏳. Residuals are all <code>uplo=&#39;U&#39;</code> at mid bandwidth: Zen5 <code>kd=128/192/256/384</code> at 0.954–0.991, Zen3 <code>kd=128/160/192</code> at 0.881–0.984 (plus <code>uplo=&#39;L&#39;</code> <code>kd=160/192</code> at 0.959–0.995). Zen3 is the worst box and also the one whose <code>_pbtrf_ucross</code> bracket is derived from a narrower <code>_vwidth</code> (W=4 → the switch lands on 192, itself a 0.90 cell), so the leading hypothesis is a candidate bracket putting the optimum at an edge — the failure this file&#39;s own history records for the wide-band panel bracket. Not yet confirmed by measurement. Correctness is clean on all three boxes (11368/11369, identical). <code>uplo=&#39;U&#39;</code> dispatches between two kernels at a measured bandwidth crossover: a conj-transpose re-pack onto the (much faster) lower kernel for narrow bands, and a native upper-storage port once the re-pack&#39;s diagonal walk starts to dominate. The panel width likewise has two measured regimes — clamping the wide-band width to <code>kd</code> collapses the in-band panel and was the routine&#39;s only Zen4 gate miss. See §5.2 and §5.3 of <a href="./tuning">Tuning</a>. <a href="#fnref7" class="footnote-backref">↩︎</a></p></li><li id="fn8" class="footnote-item"><p><strong><code>uplo=&#39;L&#39;</code> now clears OpenBLAS</strong> on the Zen4 gate sweep (geomean 1.11, worst 1.04) after the per-call overhead fix described below — but it still misses <strong>AOCL</strong> (1.17 / 0.93), so the row stays ⏳. <code>uplo=&#39;U&#39;</code> is the mirror image: 3.30 / 1.43 vs AOCL ✓ but 1.07 / <strong>0.92</strong> vs OpenBLAS. Neither triangle clears both references, and they fail against <em>different</em> ones. Historical detail, kept because the diagnosis generalises — which is why it needs both. Zen4, Float64, n = 8…2048: <code>uplo=&#39;L&#39;</code> clears OpenBLAS at every size (1.05–1.37) and clears AOCL except n=32 (<strong>0.949</strong>) and n=48 (<strong>0.980</strong>). <code>uplo=&#39;U&#39;</code> beats AOCL by a wide margin (1.17–<strong>6.27</strong>, growing with n) but loses to OpenBLAS at n=48…2048 (<strong>0.918–0.990</strong>). That 6.27× is <strong>not</strong> evidence of quality: timing the <em>same reference routine</em> under each library, AOCL&#39;s <code>dpptrf</code> <code>uplo=&#39;U&#39;</code> is <strong>6.0× slower than OpenBLAS&#39;s</strong> at n=1024 (175 281 µs vs 29 297 µs) — near-stock netlib — while on <code>dpotrf</code> the two sit within 20% of each other. AOCL optimizes dense Cholesky and does not optimize the packed variant. The gate is unchanged by this — it is <code>max(OpenBLAS, AOCL)</code>, so a slow AOCL never <em>lowers</em> the bar, it merely means <code>max()</code> here <strong>equals OpenBLAS</strong>; both references are still measured, and both sets of misses above still count. What the asymmetry does change is how much a large ratio is worth as <em>evidence</em>: a cell far above one reference and below the other is the tell that the high ratio is measuring the reference&#39;s absence, not our speed. The lower path improved this session (worst cell 0.738 → 0.949) once its gap was decomposed: the <code>spr!</code> <em>kernel</em> already ties or beats AOCL at every order, and the whole deficit was per-call overhead — the public entry plus a <code>SubArray</code> built per column — compounded by the lower path reusing the <em>upper</em> path&#39;s cutoff constant, which meant <code>spr!</code> was never called at all at n=32. See §5.3 of <a href="./tuning">Tuning</a>. The remaining cells are gaps, not ceilings. ⚠ Zen4 only; not yet fleet-validated. The committed plot SVGs/tables predate the lower-path fix. <a href="#fnref8" class="footnote-backref">↩︎</a></p></li></ol></section>',25)])])}const y=e(s,[["render",a]]);export{p as __pageData,y as default};
